// Convierte los ítems de DOS fuentes RSS en filas listas para unab.noticias.
// Filtros: publicados en los últimos 45 días (fecha actual) y temas de interés.
const DIAS = 45;
const limite = Date.now() - DIAS * 24 * 60 * 60 * 1000;
const TEMAS = /educaci[oó]n|universidad|acad[eé]mic|estudiante|tecnolog[ií]a|ingenier[ií]a|sistemas|software|convocatoria|beca|investigaci[oó]n/i;

const out = [];
const seen = new Set();

for (const item of $input.all()) {
  const j = item.json || {};
  const url = String(j.link || j.guid || '').trim();
  if (!url || seen.has(url)) continue;

  const rawTitle = String(j.title || '').trim();
  const cut = rawTitle.lastIndexOf(' - ');
  const titulo = (cut > 10 ? rawTitle.slice(0, cut) : rawTitle).slice(0, 300);
  const fuente = (cut > 10 ? rawTitle.slice(cut + 3) : (j.creator || 'Google News')).slice(0, 120);

  const clean = (html) => String(html || '')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/\s+/g, ' ')
    .trim();

  const resumen = clean(j.contentSnippet || j.content).slice(0, 600) || null;
  const contenido = clean(j.content) || null;
  const texto = (titulo + ' ' + (resumen || '')).toLowerCase();

  // Filtro temático: educación / tecnología / ingeniería de sistemas.
  if (!TEMAS.test(texto)) continue;

  const raw = j.isoDate || j.pubDate;
  let fecha = new Date().toISOString().slice(0, 10);
  let timestamp = Date.now();
  if (raw) {
    const d = new Date(raw);
    if (!isNaN(d.getTime())) {
      timestamp = d.getTime();
      fecha = d.toISOString().slice(0, 10);
    }
  }
  // Filtro temporal equivalente a CURRENT_DATE - INTERVAL '45 days' en SQL.
  if (timestamp < limite) continue;

  seen.add(url);
  let categoria = 'noticia';
  if (/(beca|financiaci|apoyo econ)/.test(texto)) categoria = 'beca';
  else if (/(convocatoria|inscripci|postulaci)/.test(texto)) categoria = 'convocatoria';
  else if (/(evento|seminario|conferencia|foro|taller)/.test(texto)) categoria = 'evento';
  else if (/(curso|diplomado|programa)/.test(texto)) categoria = 'curso';

  out.push({
    json: {
      titulo,
      resumen,
      contenido,
      url,
      fuente,
      categoria,
      fecha_publicacion: fecha,
      fecha_scrape: new Date().toISOString()
    }
  });
}

return out;

const rows = $input.all().map((i) => i.json).filter((r) => r && r.id);

if (rows.length === 0) {
  return [{ json: { enviar: false, total: 0, mensaje: 'Sin noticias nuevas.' } }];
}

const top = rows.slice(0, 5).map((n) => ({
  id: n.id,
  titulo: n.titulo,
  categoria: n.categoria,
  url: n.url
}));

return [{
  json: {
    enviar: true,
    total: rows.length,
    titulo: 'Nuevas noticias y convocatorias UNAB',
    cuerpo: rows.length === 1
      ? 'Hay una nueva publicación en el tablero UNAB.'
      : `Hay ${rows.length} nuevas publicaciones en el tablero UNAB.`,
    noticias: top
  }
}];

const input = $input.first().json;
const body = input.body ?? input;

return [{
  json: {
    session_id: String(body.session_id || body.sessionId || 'anon-' + Date.now()).slice(0, 100),
    texto: body.texto ? String(body.texto).trim() : null,
    categoria: body.categoria ? String(body.categoria).trim().toLowerCase() : null,
    canal: String(body.canal || 'android').slice(0, 20),
    inicio_ms: Date.now()
  }
}];

const ctx = $('Normalizar Consulta').first().json;
const rows = $input.all().map((i) => i.json).filter((r) => r && r.titulo);

const respuesta = rows.length
  ? `Se encontraron ${rows.length} noticias o convocatorias.`
  : 'No se encontraron noticias o convocatorias con ese filtro.';

return [{
  json: {
    ok: true,
    total: rows.length,
    noticias: rows,
    session_id: ctx.session_id,
    canal: ctx.canal,
    id_estudiante: null,
    pregunta: ctx.texto || 'Noticias y convocatorias UNAB',
    respuesta,
    tipo: 'noticias',
    fuentes: [],
    latencia_ms: Math.max(0, Date.now() - ctx.inicio_ms)
  }
}];
